function ising_critical_constants():
    L <- log(1 + sqrt(2))
    beta_c <- L / 2
    T_c <- 2 / L
    return (beta_c, T_c)

function verify():
    (beta_c, T_c) <- ising_critical_constants()
    assert sinh(2 * beta_c) approx 1
    assert T_c * beta_c approx 1
    return true

function dual_beta(beta):
    return (1/2) * arcsinh(1 / sinh(2 * beta))

function is_fixed_point(beta, tol):
    return |dual_beta(beta) - beta| < tol

